class TestTimestampSignerTimedelta:
    """Tests for timedelta support in TimestampSigner.max_age."""

    @pytest.fixture()
    def signer(self):
        return TimestampSigner("secret-key")

    @pytest.fixture()
    def ts(self):
        return timezone.utc.fromtimestamp(1000000)

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_accepted(self, signer, ts):
        signed = signer.sign("value")
        result = signer.unsign(signed, max_age=timedelta(seconds=10))
        assert result == b"value"

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_expired(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:55"):
            with pytest.raises(SignatureExpired):
                signer.unsign(signed, max_age=timedelta(seconds=10))

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_zero(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:40"):
            result = signer.unsign(signed, max_age=timedelta(seconds=0))
            assert result == b"value"

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_negative(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:40"):
            with pytest.raises(SignatureExpired):
                signer.unsign(signed, max_age=timedelta(seconds=-1))

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_fractional(self, signer, ts):
        signed = signer.sign("value")
        result = signer.unsign(signed, max_age=timedelta(milliseconds=500))
        assert result == b"value"

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_exact_boundary(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:50"):
            result = signer.unsign(signed, max_age=timedelta(seconds=10))
            assert result == b"value"

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_future_rejected(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:30"):
            with pytest.raises(SignatureExpired):
                signer.unsign(signed, max_age=timedelta(seconds=10))

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_validate_true(self, signer, ts):
        signed = signer.sign("value")
        assert signer.validate(signed, max_age=timedelta(seconds=10)) is True

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_validate_false(self, signer, ts):
        signed = signer.sign("value")
        with freeze_time("2001-09-09 01:46:55"):
            assert signer.validate(signed, max_age=timedelta(seconds=10)) is False

    def test_timedelta_invalid_type(self, signer):
        signed = signer.sign("value")
        with pytest.raises(TypeError):
            signer.unsign(signed, max_age="10")

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_return_timestamp(self, signer, ts):
        signed = signer.sign("value")
        payload, dt = signer.unsign(
            signed, max_age=timedelta(seconds=10), return_timestamp=True
        )
        assert payload == b"value"
        assert dt == ts

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_none_still_works(self, signer, ts):
        signed = signer.sign("value")
        result = signer.unsign(signed, max_age=None)
        assert result == b"value"

    @freeze_time("2001-09-09 01:46:40")
    def test_timedelta_large_int(self, signer, ts):
        signed = signer.sign("value")
        result = signer.unsign(signed, max_age=2**54)
        assert result == b"value"


